const { env } = await import('node:process');
if (!env.HTML_INPUT) { throw new Error('Missing HTML_INPUT'); }
globalThis.html = env.HTML_INPUT;

const mod = await import('topdf');
const fn = mod.default || mod;
if (typeof fn !== 'function') { throw new Error('topdf export is not a function'); }
const pdfBuffer = fn(globalThis.html);
if (!pdfBuffer || typeof pdfBuffer.toString !== 'function') { throw new Error('Invalid PDF buffer'); }
globalThis.pdfBase64 = pdfBuffer.toString('base64');
